import os
wd = os.environ['TRAJECTORY_WORKDIR']
for root, dirs, files in os.walk(wd):
    # skip memory dir
    if 'memory' in root.split('/'):
        continue
    rel = os.path.relpath(root, wd)
    print(rel)
    for f in files:
        p = os.path.join(root, f)
        try:
            sz = os.path.getsize(p)
        except OSError:
            sz = -1
        print(f"  {f} ({sz})")

from IPython.display import Image, display
