    "Ermolai 2024 multi-material FDM dovetail T-slot joint tensile strength",
    "PETG TPU interfacial adhesion fused deposition modeling 2024",
    "print-in-place captive joint multi-material FDM clearance",
    "Frascio 2024 multi-material additive manufacturing joint",
]
results = {}
for q in queries:
    try:
        r = await web_search(q, category="scholarly", num_results=5)
        results[q] = r
    except Exception as e:
        results[q] = f"ERR {e}"
for q, r in results.items():
    print("==", q)
    if isinstance(r, str):
        print(r); continue
    for hit in r[:5]:
        print(" -", hit.get('title'), "|", hit.get('url'), "|", hit.get('publishedDate'))

